class MockTarget:
    """Minimal ChaosTarget implementation for testing."""

    def __init__(self, name: str = "mock-target") -> None:
        self.name = name
        self.injected_faults: list[FaultSpec] = []
        self.recovered_faults: list[FaultSpec] = []
        self.fail_on_inject = False
        self.fail_on_recover = False

    async def inject_fault(self, spec: FaultSpec) -> None:
        if self.fail_on_inject:
            raise RuntimeError("inject failure")
        self.injected_faults.append(spec)

    async def recover_fault(self, spec: FaultSpec) -> None:
        if self.fail_on_recover:
            raise RuntimeError("recover failure")
        self.recovered_faults.append(spec)


class TestChaosTargetProtocol:
    """Verify protocol conformance and behavior."""

    def test_mock_target_conforms(self) -> None:
        assert isinstance(MockTarget(), ChaosTarget)

    def test_inject_and_recover(self) -> None:
        target = MockTarget()
        spec = FaultSpec(type=FaultType.DELAY, target="x")

        async def run() -> None:
            await target.inject_fault(spec)
            await target.recover_fault(spec)

        asyncio.run(run())
        assert target.injected_faults == [spec]
        assert target.recovered_faults == [spec]

    def test_inject_failure_propagates(self) -> None:
        target = MockTarget()
        target.fail_on_inject = True
        spec = FaultSpec(type=FaultType.DELAY, target="x")

        async def run() -> None:
            with pytest.raises(RuntimeError, match="inject failure"):
                await target.inject_fault(spec)

        asyncio.run(run())

    def test_recover_failure_propagates(self) -> None:
        target = MockTarget()
        target.fail_on_recover = True
        spec = FaultSpec(type=FaultType.DELAY, target="x")

        async def run() -> None:
            with pytest.raises(RuntimeError, match="recover failure"):
                await target.recover_fault(spec)

        asyncio.run(run())


