class TestChaosEngineCancellation:
    """Cancellation and timeout handling."""

    def test_cancel_running_engine(self) -> None:
        engine = ChaosEngine()
        target = MockTarget("svc-a")
        engine.register_target("svc-a", target)
        spec = FaultSpec(type=FaultType.DELAY, target="svc-a", duration_ms=5000)
        engine.add_spec(spec)

        async def run() -> None:
            task = asyncio.create_task(engine.execute_once())
            await asyncio.sleep(0.01)
            task.cancel()
            with pytest.raises(asyncio.CancelledError):
                await task

        asyncio.run(run())

    def test_timeout_raises(self) -> None:
        engine = ChaosEngine()
        target = MockTarget("svc-a")
        engine.register_target("svc-a", target)
        spec = FaultSpec(type=FaultType.DELAY, target="svc-a", duration_ms=5000)
        engine.add_spec(spec)

        async def run() -> None:
            with pytest.raises(asyncio.TimeoutError):
                await asyncio.wait_for(engine.execute_once(), timeout=0.05)

        asyncio.run(run())


class TestChaosEngineConcurrency:
    """Concurrent execution and race detection."""

    def test_parallel_execution_no_race(self) -> None:
        engine = ChaosEngine()
        targets = {f"svc-{i}": MockTarget(f"svc-{i}") for i in range(10)}
        for name, target in targets.items():
            engine.register_target(name, target)
            engine.add_spec(FaultSpec(type=FaultType.DELAY, target=name, duration_ms=1))

        async def run() -> None:
            await asyncio.gather(*[engine.execute_once() for _ in range(5)])

        asyncio.run(run())
        for target in targets.values():
            assert len(target.injected_faults) == 5
            assert len(target.recovered_faults) == 5

    def test_concurrent_register_target(self) -> None:
        engine = ChaosEngine()

        async def register_many() -> None:
            await asyncio.gather(
                *[
                    asyncio.to_thread(engine.register_target, f"svc-{i}", MockTarget(f"svc-{i}"))
                    for i in range(20)
                ]
            )

        asyncio.run(register_many())
        assert len(engine.targets) == 20


