class TestPropertyBasedValidation:
    """Hypothesis-driven property tests."""

    @given(st.floats(min_value=0.0, max_value=1.0))
    def test_probability_always_valid(self, prob: float) -> None:
        spec = FaultSpec(type=FaultType.DELAY, target="x", probability=prob)
        assert 0.0 <= spec.probability <= 1.0

    @given(st.integers(min_value=0, max_value=10_000))
    def test_duration_always_non_negative(self, duration: int) -> None:
        spec = FaultSpec(type=FaultType.DELAY, target="x", duration_ms=duration)
        assert spec.duration_ms >= 0

    @given(st.sampled_from(list(FaultType)))
    def test_all_fault_types_constructible(self, fault_type: FaultType) -> None:
        spec = FaultSpec(type=fault_type, target="x")
        assert spec.type == fault_type

    @given(st.sampled_from(list(FaultSeverity)))
    def test_all_severities_constructible(self, severity: FaultSeverity) -> None:
        spec = FaultSpec(type=FaultType.DELAY, target="x", severity=severity)
        assert spec.severity == severity

    @given(st.text(min_size=1, max_size=100))
    def test_non_empty_target_accepted(self, target: str) -> None:
        spec = FaultSpec(type=FaultType.DELAY, target=target)
        assert spec.target == target

    @settings(max_examples=50)
    @given(
        st.lists(
            st.builds(
                FaultSpec,
                type=st.sampled_from(list(FaultType)),
                target=st.text(min_size=1, max_size=50),
                severity=st.sampled_from(list(FaultSeverity)),
                probability=st.floats(min_value=0.0, max_value=1.0),
                duration_ms=st.integers(min_value=0, max_value=5000),
            ),
            min_size=1,
            max_size=20,
        )
    )
    def test_batch_specs_all_valid(self, specs: list[FaultSpec]) -> None:
        for spec in specs:
            assert spec.validate_spec() is True


