class TestIntegrationScenarios:
    """End-to-end scenarios combining multiple features."""

    def test_full_lifecycle(self) -> None:
        engine = ChaosEngine()
        targets = {
            "api": MockTarget("api"),
            "db": MockTarget("db"),
            "cache": MockTarget("cache"),
        }
        for name, target in targets.items():
            engine.register_target(name, target)

        specs = [
            FaultSpec(type=FaultType.DELAY, target="api", duration_ms=10, probability=1.0),
            FaultSpec(type=FaultType.PARTITION, target="db", duration_ms=20, probability=0.5),
            FaultSpec(type=FaultType.CORRUPT, target="cache", duration_ms=5, probability=0.0),
        ]
        for spec in specs:
            engine.add_spec(spec)

        async def run() -> None:
            await engine.execute_once()
            assert len(targets["api"].injected_faults) == 1
            assert len(targets["db"].injected_faults) in (0, 1)
            assert targets["cache"].injected_faults == []
            assert await engine.verify_all_recovered() is True

        asyncio.run(run())

    def test_multiple_execution_cycles(self) -> None:
        engine = ChaosEngine()
        target = MockTarget("svc-a")
        engine.register_target("svc-a", target)
        engine.add_spec(FaultSpec(type=FaultType.DELAY, target="svc-a", duration_ms=1, probability=1.0))

        async def run() -> None:
            for _ in range(10):
                await engine.execute_once()

        asyncio.run(run())
        assert len(target.injected_faults) == 10
        assert len(target.recovered_faults) == 10

    def test_error_isolation_between_targets(self) -> None:
        engine = ChaosEngine()
        good_target = MockTarget("good")
        bad_target = MockTarget("bad")
        bad_target.fail_on_inject = True
        engine.register_target("good", good_target)
        engine.register_target("bad", bad_target)
        engine.add_spec(FaultSpec(type=FaultType.DELAY, target="good", duration_ms=1))
        engine.add_spec(FaultSpec(type=FaultType.DELAY, target="bad", duration_ms=1))

        with pytest.raises(RuntimeError):
            asyncio.run(engine.execute_once())
        # Good target should still have been processed
        assert len(good_target.injected_faults) == 1


